(() => {
  const meta = (sel) => { const el = document.querySelector(sel); return el ? (el.getAttribute('content') || '') : ''; };
  const og = meta('meta[property="og:description"]');
  const nodes = [...document.querySelectorAll('div[data-pressable-container] span, article span')];
  let best = '';
  for (const n of nodes) {
    const t = (n.innerText || '').trim();
    if (t.length > best.length && !/^(\d+[smhd]|\d+ (likes?|replies|reposts?))$/.test(t)) best = t;
  }
  const body = document.body ? document.body.innerText : '';
  return JSON.stringify({
    url: location.href,
    title: document.title,
    ogTitle: meta('meta[property="og:title"]'),
    ogDescription: og,
    ogSite: 'threads',
    author: (location.pathname.match(/^\/@([^/]+)/) || [])[1] || meta('meta[name="author"]'),
    published: meta('meta[property="article:published_time"]'),
    text: (best || og || body).slice(0, 8000)
  });
})()
